REPLACE INTO ?:nomenclature_node_descriptions (node_id, name, description, lang_code) VALUES('9', 'Ergom (vendor page)', '<p>Vendor page of the Ergom brand. It shows the product range supplied by this vendor and is used as an entry point to the manufacturer catalog.</p><p><b>What is inside:</b><ul><li>The positions supplied by the vendor.</li><li>Short description of the brand and its position in the catalog.</li></ul>', 'en');
REPLACE INTO ?:nomenclature_node_descriptions (node_id, name, description, lang_code) VALUES('10', 'Ergom PRO (vendor page)', '<p>Vendor page of the Ergom PRO line. The page is bound to the vendor and shows only the products of this manufacturer.</p><p>The manufacturer list on the storefront is built from pages of this type, so each vendor brand gets its own entry in the catalog.</p>', 'en');